$output = Join-Path $PSScriptRoot '..\public\images'
New-Item -ItemType Directory -Path $output -Force | Out-Null

foreach ($entry in $assets.GetEnumerator()) {
  $destination = Join-Path $output $entry.Key
  if (-not (Test-Path -LiteralPath $destination)) {
    Invoke-WebRequest -Uri $entry.Value -OutFile $destination
  }
  Write-Output "$($entry.Key): $((Get-Item -LiteralPath $destination).Length) bytes"
}
